INSERT INTO catalog_title (title_id, minimum_tier_id, title_name, maturity_rating, content_type, synopsis) VALUES
  ('34088d5c-dc47-4040-94fb-b64d2e154a00', 0, 'Dick Johnson Is Dead', 'PG-13', 'Movie', 'As her father nears the end of his life, filmmaker Kirsten Johnson stages his death in inventive and comical ways to help them both face the inevitable.'),
  ('ff7f6378-6f13-4071-83a3-b127248fd717', 1, 'My Little Pony: A New Generation', 'PG', 'Movie', 'Equestria''s divided. But a bright-eyed hero believes Earth Ponies, Pegasi and Unicorns should be pals — and, hoof to heart, she’s determined to prove it.'),
  ('421fa2fe-a2ff-4908-a52c-900be5895a6f', 2, 'Sankofa', 'R', 'Movie', 'On a photo shoot in Ghana, an American model slips back in time, becomes enslaved on a plantation and bears witness to the agony of her ancestral past.'),
  ('c0cdbdc1-5074-439c-92d5-cd7c8c23cdf5', 3, 'The Starling', 'PG-13', 'Movie', 'A woman adjusting to life after a loss contends with a feisty bird that''s taken over her garden — and a husband who''s struggling to find a way forward.'),
  ('130e9b2b-b5fa-4b51-bbbe-f537dbc92a24', 0, 'Je Suis Karl', 'R', 'Movie', 'After most of her family is murdered in a terrorist bombing, a young woman is unknowingly lured into joining the very group that killed them.'),
  ('aa37f8b6-4522-4060-98b2-03a2ce362797', 1, 'Confessions of an Invisible Girl', 'PG', 'Movie', 'When the clever but socially-awkward Tetê joins a new school, she''ll do anything to fit in. But the queen bee among her classmates has other ideas.'),
  ('4869f5eb-8ef6-4cb2-b8cc-af498fa7e5e0', 2, 'Europe''s Most Dangerous Man: Otto Skorzeny in Spain', 'R', 'Movie', 'Declassified documents reveal the post-WWII life of Otto Skorzeny, a close Hitler ally who escaped to Spain and became an adviser to world presidents.'),
  ('cdbeed52-bbf5-4e37-acd2-ad14c6fe9972', 3, 'Intrusion', 'PG-13', 'Movie', 'After a deadly home invasion at a couple’s new dream house, the traumatized wife searches for answers — and learns the real danger is just beginning.'),
  ('6960d311-78c0-47cb-8a5e-9f1f6c52eab7', 0, 'Avvai Shanmughi', 'PG', 'Movie', 'Newly divorced and denied visitation rights with his daughter, a doting father disguises himself as a gray-haired nanny in order to spend time with her.'),
  ('167b24fe-df26-4c9f-b6a0-49ce7cb1023d', 1, 'Go! Go! Cory Carson: Chrissy Takes the Wheel', 'G', 'Movie', 'From arcade games to sled days and hiccup cures, Cory Carson’s curious little sister Chrissy speeds off on her own for fun and adventure all over town!'),
  ('6d7fdc59-44cf-44cc-9620-aecb81709680', 2, 'Jeans', 'PG-13', 'Movie', 'When the father of the man she loves insists that his twin sons marry twin sisters, a woman creates an alter ego that might be a bit too convincing.'),
  ('c30e3684-2572-4291-a04f-5f329c3b835c', 3, 'Minsara Kanavu', 'PG', 'Movie', 'A tangled love triangle ensues when a man falls for a woman studying to become a nun — and she falls for the friend he enlists to help him pursue her.'),
  ('0a339857-3af8-4cfe-b448-386bc7b2317b', 0, 'Grown Ups', 'PG-13', 'Movie', 'Mourning the loss of their beloved junior high basketball coach, five middle-aged pals reunite at a lake house and rediscover the joys of being a kid.'),
  ('383667f4-b10c-4441-a442-49f4bbcfebc8', 1, 'Dark Skies', 'PG-13', 'Movie', 'A family’s idyllic suburban life shatters when an alien force invades their home, and as they struggle to convince others of the deadly threat.'),
  ('9cf392c5-56db-4e33-83c7-7ad1674c6334', 2, 'Paranoia', 'PG-13', 'Movie', 'Blackmailed by his company''s CEO, a low-level employee finds himself forced to spy on the boss''s rival and former mentor.'),
  ('3cfc1f40-8dbc-49ae-afb9-a1273d397804', 3, 'Ankahi Kahaniya', 'PG-13', 'Movie', 'As big city life buzzes around them, lonely souls discover surprising sources of connection and companionship in three tales of love, loss and longing.'),
  ('858806a0-4d0f-470a-b102-5efd03107bf7', 0, 'The Father Who Moves Mountains', 'R', 'Movie', 'When his son goes missing during a snowy hike in the mountains, a retired intelligence officer will stop at nothing — and risk everything — to find him.'),
  ('01367308-822a-4c5b-bb79-e9bd26f224ef', 1, 'The Stronghold', 'R', 'Movie', 'Tired of the small-time grind, three Marseille cops get a chance to bust a major drug network. But lines blur when a key informant makes a big ask.'),
  ('ae5434ee-e88b-43c7-b16b-37bd913d53b8', 2, 'Birth of the Dragon', 'PG-13', 'Movie', 'A young Bruce Lee angers kung fu traditionalists by teaching outsiders, leading to a showdown with a Shaolin master in this film based on real events.'),
  ('446883d1-fa3e-4315-b7cf-8f541f43195a', 3, 'Jaws', 'PG', 'Movie', 'When an insatiable great white shark terrorizes Amity Island, a police chief, an oceanographer and a grizzled shark hunter seek to destroy the beast.'),
  ('d56c0ce5-e34d-46b1-883c-b884d2bbc0f1', 0, 'Jaws 2', 'PG', 'Movie', 'Four years after the last deadly shark attacks, police chief Martin Brody fights to protect Amity Island from another killer great white.'),
  ('b71432f2-9118-4473-abb6-46b95992f3a2', 1, 'Jaws 3', 'PG', 'Movie', 'After the staff of a marine theme park try to capture a young great white shark, they discover its mother has invaded the enclosure and is out for blood.'),
  ('8d941bb0-fa3d-4668-860d-a8ab091fbb07', 2, 'Jaws: The Revenge', 'PG-13', 'Movie', 'After another deadly shark attack, Ellen Brody has had enough of Amity Island and moves to the Caribbean – but a great white shark follows her there.'),
  ('15bb8e08-5342-4237-b8fa-b3d01e154c7b', 3, 'My Heroes Were Cowboys', 'PG', 'Movie', 'Robin Wiltshire''s painful childhood was rescued by Westerns. Now he lives on the frontier of his dreams, training the horses he loves for the big screen.'),
  ('8f2d0b45-9e7e-43c7-a5dd-3db4de877f76', 0, 'Safe House', 'R', 'Movie', 'Young CIA operative Matt Weston must get a dangerous criminal out of an agency safe house that''s come under attack and get him to a securer location.'),
  ('f1697e93-2f3b-49d2-a477-eafe02f43a76', 1, 'Training Day', 'R', 'Movie', 'A rookie cop with one day to prove himself to a veteran LAPD narcotics officer receives a crash course in his mentor''s questionable brand of justice.'),
  ('ac5196f8-35f1-4eaf-b923-25274a907ea9', 2, 'InuYasha the Movie 2: The Castle Beyond the Looking Glass', 'PG-13', 'Movie', 'With their biggest foe seemingly defeated, InuYasha and his friends return to everyday life. But the peace is soon shattered by an emerging new enemy.'),
  ('1b967f91-c998-4cfc-abad-7d4dfc108a67', 3, 'InuYasha the Movie 3: Swords of an Honorable Ruler', 'PG-13', 'Movie', 'The Great Dog Demon beaqueathed one of the Three Swords of the Fang to each of his two sons. Now the evil power of the third sword has been awakened.'),
  ('7b7f1816-57aa-40f2-9f46-ac5d5ab78a58', 0, 'InuYasha the Movie 4: Fire on the Mystic Island', 'PG', 'Movie', 'Ai, a young half-demon who has escaped from Horai Island to try to help her people, returns with potential saviors InuYasha, Sesshomaru and Kikyo.'),
  ('bb7c7bd0-4cf5-4ee8-b1d1-f889a02c6ec3', 1, 'InuYasha the Movie: Affections Touching Across Time', 'PG', 'Movie', 'A powerful demon has been sealed away for 200 years. But when the demon''s son is awakened, the fate of the world is in jeopardy.'),
  ('0ae95c37-97a2-48ba-89df-5b71d9312b54', 2, 'Naruto Shippuden the Movie: Blood Prison', 'PG-13', 'Movie', 'Mistakenly accused of an attack on the Fourth Raikage, ninja Naruto is imprisoned in the impenetrable Hozuki Castle and his powers are sealed.'),
  ('e1818a98-a849-4b7d-a53f-bf8d47b846db', 3, 'Naruto Shippûden the Movie: Bonds', 'PG', 'Movie', 'When strange ninjas ambush the village of Konohagakure, it''s up to adolescent ninja Naruto and his long-missing pal, Sasuke, to save the planet.'),
  ('72c100ee-e817-4abb-a8a0-c02d9399335a', 0, 'Naruto Shippûden the Movie: The Will of Fire', 'PG', 'Movie', 'When four out of five ninja villages are destroyed, the leader of the one spared tries to find the true culprit and protect his land.'),
  ('59af5b63-6ed5-44f7-ab10-2e16bcab5a71', 1, 'Naruto Shippuden: The Movie', 'PG', 'Movie', 'The adventures of adolescent ninja Naruto Uzumaki continue as he''s tasked with protecting a priestess from a demon – but to do so, he must die.'),
  ('707f5cec-66fa-47b3-b8a4-478adeaf1611', 2, 'Naruto Shippuden: The Movie: The Lost Tower', 'PG-13', 'Movie', 'When Naruto is sent to recover a missing nin, the rogue manages to send him 20 years into the past, where he unites with his father to battle evil.'),
  ('2268cd1d-40c9-4e05-b876-fbe1bf724d95', 3, 'Naruto the Movie 2: Legend of the Stone of Gelel', 'PG', 'Movie', 'While on a mission to return a missing pet, Naruto and two fellow ninjas are ambushed by brutal knights led by the enigmatic Temujin.'),
  ('05f9c8a4-05a1-4bd8-a593-c9e572577ae1', 0, 'Naruto the Movie 3: Guardians of the Crescent Moon Kingdom', 'PG', 'Movie', 'Exuberant ninja Naruto teams up with his pals Sakura and Kakashi to escort Prince Michiru and his son, Hikaru, to the Crescent Moon kingdom.'),
  ('0a363e23-4f3a-491b-9c57-3cdeb962760b', 1, 'Naruto the Movie: Ninja Clash in the Land of Snow', 'PG', 'Movie', 'Naruto, Sasuke and Sakura learn they''ll be protecting an actress from being hurt while making her next film, but it turns out she''s a princess.'),
  ('57a17b4c-2493-4167-adef-11ed208e3aed', 2, 'Nightbooks', 'PG', 'Movie', 'Scary story fan Alex must tell a spine-tingling tale every night — or stay trapped with his new friend in a wicked witch''s magical apartment forever.'),
  ('4adb701b-0fc9-44cf-b0b5-d72a5a3850c9', 3, 'Schumacher', 'PG-13', 'Movie', 'Through exclusive interviews and archival footage, this documentary traces an intimate portrait of seven-time Formula 1 champion Michael Schumacher.'),
  ('6c8b372a-2955-4eca-8a86-be256433eb12', 0, 'A StoryBots Space Adventure', 'G', 'Movie', 'Join the StoryBots and the space travelers of the historic Inspiration4 mission as they search for answers to kids'' questions about space.'),
  ('e0493a00-9cba-4ed3-b52a-bcf37fd1a29e', 1, 'King of Boys', 'R', 'Movie', 'When a powerful businesswoman’s political ambitions are threatened by her underworld connections, the ensuing power struggle could cost her everything.'),
  ('6bc129b2-df34-4fe1-874c-fc7b7480e6a9', 2, 'You vs. Wild: Out Cold', 'G', 'Movie', 'After a plane crash leaves Bear with amnesia, he must make choices to save the missing pilot and survive in this high-stakes interactive adventure.'),
  ('3f11a717-2b81-4cbc-b486-e3d7477aefa0', 3, 'Little Singham - Black Shadow', 'G', 'Movie', 'Kid cop Little Singham loses all his superpowers while trying to stop the demon Kaal’s new evil plans! Can his inner strength help him defeat the enemy?'),
  ('b3addae6-686d-4772-9031-9abb0e80dfda', 0, 'Tughlaq Durbar', 'PG-13', 'Movie', 'A budding politician has devious plans to rise in the ranks — until an unexpected new presence begins to interfere with his every crooked move.'),
  ('0b1711f7-2672-4f40-8e94-c3172204d4e8', 1, 'Tughlaq Durbar (Telugu)', 'PG-13', 'Movie', 'A budding politician has devious plans to rise in the ranks — until an unexpected new presence begins to interfere with his every crooked move.'),
  ('7736d763-9135-4b9d-b807-75528a8d22b1', 2, 'Firedrake the Silver Dragon', 'G', 'Movie', 'When his home is threatened by humans, a young dragon summons the courage to seek a mythical paradise where dragons can live in peace and fly free.'),
  ('ad22fe35-f817-4333-9187-581547722b90', 3, 'Kate', 'R', 'Movie', 'Slipped a fatal poison on her final job, a ruthless assassin working in Tokyo has less than 24 hours to find out who ordered the hit and exact revenge.'),
  ('fcaa06e2-5c8b-4467-a0ed-ab958aedadaf', 0, 'Omo Ghetto: the Saga', 'R', 'Movie', 'Twins are reunited as a good-hearted female gangster and her uptight rich sister take on family, crime, cops and all of the trouble that follows them.'),
  ('b5294cf5-4e5f-4155-a782-ebce77d913b6', 1, 'Prey', 'R', 'Movie', 'A hiking trip into the wild turns into a desperate bid for survival for five friends on the run from a mysterious shooter.');
INSERT INTO catalog_title (title_id, minimum_tier_id, title_name, maturity_rating, content_type, synopsis) VALUES
  ('9218f06d-38c9-45b1-8be3-e663a9215dd5', 2, 'Blood Brothers: Malcolm X & Muhammad Ali', 'PG-13', 'Movie', 'From a chance meeting to a tragic fallout, Malcolm X and Muhammad Ali''s extraordinary bond cracks under the weight of distrust and shifting ideals.'),
  ('782ff5b4-9bbf-429e-a4cb-ac954cf01cd3', 3, 'Paradise Hills', 'R', 'Movie', 'Uma wakes up in a lush tropical facility designed to turn willful girls into perfect ladies. That’s bad enough, but its real purpose is even worse.'),
  ('d87df7cc-e68f-4d79-93b5-91f20620a349', 0, 'The Women and the Murderer', 'PG-13', 'Movie', 'This documentary traces the capture of serial killer Guy Georges through the tireless work of two women: a police chief and a victim''s mother.'),
  ('dd0741dd-e0bb-4b6c-922c-c20c4e63ceec', 1, 'JJ+E', 'R', 'Movie', 'Elisabeth and John-John live in the same city, but they inhabit different worlds. Can a passionate first love break through class and cultural barriers?'),
  ('157e50b5-8f23-4324-83c0-58ae1040e324', 2, 'Show Dogs', 'PG', 'Movie', 'A rough and tough police dog must go undercover with an FBI agent as a prim and proper pet at a dog show to save a baby panda from an illegal sale.'),
  ('963268db-5737-48e4-a49b-ef59df8db928', 3, 'If I Leave Here Tomorrow: A Film About Lynyrd Skynyrd', 'R', 'Movie', 'Using interviews and archival footage, this documentary charts the story of the legendary Southern rockers with a focus on front man Ronnie Van Zant.'),
  ('3055dd10-de20-4390-a2b7-0a3b41b28870', 0, 'Untold: Breaking Point', 'R', 'Movie', 'Under pressure to continue a winning tradition in American tennis, Mardy Fish faced mental health challenges that changed his life on and off the court.'),
  ('409a9248-dac5-456a-b0f0-7f7c5141ff74', 1, 'Shadow Parties', 'R', 'Movie', 'A family faces destruction in a long-running conflict between communities that pits relatives against each other amid attacks and reprisals.'),
  ('99ad5d2f-7624-4039-a988-d5fbaa1866b6', 2, 'Angamaly Diaries', 'PG-13', 'Movie', 'After growing up amidst the gang wars of his hometown, Vincent forms an entrepreneurial squad of his own and ends up on the wrong side of the law.'),
  ('5cb01816-cd63-4de3-983f-63bdf7593ab4', 3, 'A Champion Heart', 'G', 'Movie', 'When a grieving teen must work off her debt to a ranch, she cares for a wounded horse that teaches her more about healing than she expected.'),
  ('8e28b475-2276-495b-a653-01ad0ff222a2', 0, 'Worth', 'PG-13', 'Movie', 'In the wake of the Sept. 11 attacks, a lawyer faces an emotional reckoning as he attempts to put a dollar value on the lives lost. Based on real events.'),
  ('804a7c32-f695-49f2-a5b9-5a0b06c12ba8', 1, 'Afterlife of the Party', 'PG', 'Movie', 'Cassie lives to party... until she dies in a freak accident. Now this social butterfly needs to right her wrongs on Earth if she wants to earn her wings.'),
  ('af957dea-20ee-4771-86d7-f5a50ce3badf', 2, 'Anjaam', 'PG-13', 'Movie', 'A wealthy industrialist’s dangerous obsession with a flight attendant destroys her world, until she takes matters into her own hands to exact revenge.'),
  ('023b0c74-5cd1-404d-9639-7db3581c8f4a', 3, 'Bright Star', 'PG', 'Movie', 'This drama details the passionate three-year romance between Romantic poet John Keats – who died tragically at age 25 – and his great love and muse.'),
  ('f64b9f49-0bb1-4022-a226-97204a3a21e6', 0, 'Dhanak', 'PG', 'Movie', 'A movie-loving 10-year-old and her blind little brother trek to meet Indian superstar Shah Rukh Khan for help in getting the boy an eye operation.'),
  ('d4fc8ab0-b9da-461f-8b60-7397a586027e', 1, 'Final Account', 'PG-13', 'Movie', 'This documentary stitches together never-before-seen interviews with the last living generation of people who participated in Hitler''s Third Reich.'),
  ('d9445a3c-fcad-4273-b46f-8d4d22fca5fb', 2, 'Gurgaon', 'PG-13', 'Movie', 'When the daughter of a wealthy family returns from college, she gets a frosty welcome from her brother, who has problems – and plans – of his own.'),
  ('0d619663-8342-4bca-9f7b-55c04035630d', 3, 'Here and There', 'R', 'Movie', 'After meeting through a heated exchange on social media, two people with different backgrounds begin an online romance in the midst of a pandemic.'),
  ('f50bd7c6-2093-4c40-8e9b-2a21381b0635', 0, 'In the Cut', 'R', 'Movie', 'After embarking on an affair with the cop probing the murder of a young woman, an insular schoolteacher suspects her lover was involved in the crime.'),
  ('d9797362-6e2c-4edf-a6b1-2e995e83f7f6', 1, 'Shikara', 'PG-13', 'Movie', 'A couple must strive to remain resilient after regional hostilities drive them from their beloved home into a refugee camp.'),
  ('b132356c-bf03-4edc-a433-103c77257f15', 2, 'A Cinderella Story', 'PG', 'Movie', 'Teen Sam meets the boy of her dreams at a dance before returning to toil in her stepmother''s diner. Can her lost cell phone bring them together?'),
  ('9fc9af9e-9be5-4170-adcd-ea16ed20f054', 3, 'Agatha Christie''s Crooked House', 'PG-13', 'Movie', 'When a detective investigates the death of his ex-lover''s grandfather, he uncovers secrets about the tycoon''s manipulative family.'),
  ('fa505e25-dc7d-43c1-95c5-c1f5704c1470', 0, 'An Unfinished Life', 'PG-13', 'Movie', 'A grieving widow and her daughter move in with her estranged father-in-law in Wyoming, where time allows them to heal and forgive.'),
  ('17fc3937-7250-488c-876a-a2d371f74cc7', 1, 'Barbie Big City Big Dreams', 'G', 'Movie', 'At a summer performing arts program in New York City, Barbie from Malibu meets Barbie from Brooklyn, and the two become fast friends.'),
  ('4b747ff0-b9f6-4db9-b568-7e73d5d9a8c4', 2, 'Blade Runner: The Final Cut', 'R', 'Movie', 'In a smog-choked dystopian Los Angeles, blade runner Rick Deckard is called out of retirement to snuff a quartet of escaped "replicants."'),
  ('550d0f57-9487-4ccd-8234-c4ef409fd705', 3, 'Chappie', 'R', 'Movie', 'In a futuristic society where an indestructible robot police force keeps crime at bay, a lone droid evolves to the next level of artificial intelligence.'),
  ('1a640f65-07c8-447f-a522-a5fec1adec9e', 0, 'Clear and Present Danger', 'PG-13', 'Movie', 'When the president''s friend is murdered, CIA Deputy Director Jack Ryan becomes unwittingly involved in an illegal war against a Colombian drug cartel.'),
  ('fe43bb88-e522-40a7-b586-0d926e6042db', 1, 'Cliffhanger', 'R', 'Movie', 'Ranger Gabe Walker and his partner are called to rescue a group of stranded climbers, only to learn the climbers are actually thieving hijackers.'),
  ('d69f939d-afed-4bcc-9ac5-f4a17245bd96', 2, 'Cold Mountain', 'R', 'Movie', 'This drama follows a wounded Civil War soldier making the long journey home, while his faraway love fights for survival on her deceased father''s farm.'),
  ('d1112e31-5a0a-4e4b-aafc-e2df9686cbfe', 3, 'Crocodile Dundee in Los Angeles', 'PG', 'Movie', 'When Mick "Crocodile" Dundee and his family land in Los Angeles, they soon learn some lessons about American life in this comedy sequel.'),
  ('e043c81d-06cc-48fe-8fe1-078a2a8c3b12', 0, 'Dear John', 'PG-13', 'Movie', 'While on summer leave, a U.S. soldier falls for a college student. But when he''s forced to reenlist, their handwritten letters hold the lovers together.'),
  ('ae7a9fea-7ccf-4b44-86d9-674951083691', 1, 'Do the Right Thing', 'R', 'Movie', 'On a sweltering day in Brooklyn, simmering racial tensions between residents rise to the surface and ignite rage, violence and tragedy.'),
  ('9bf55255-da7a-48f2-af45-b022a938523f', 2, 'El patrón, radiografía de un crimen', 'R', 'Movie', 'A lawyer defends an illiterate man whose exploitation by a cruel boss while working as a butcher in Buenos Aires led to tragedy. Based on a true case.'),
  ('f7d89cab-11dd-4179-b3fc-112382480840', 3, 'Extraction', 'R', 'Movie', 'When a retired CIA agent is kidnapped, his son, a government analyst, embarks on an unauthorized mission to find him and halt a terrorist plot.'),
  ('591945fd-29d3-4110-bb2d-8fb776758375', 0, 'Freedom Writers', 'PG-13', 'Movie', 'While her at-risk students are reading classics such as "The Diary of Anne Frank," a teacher asks them to keep journals about their troubled lives.'),
  ('dc3ec8f3-6478-4924-bcd0-390aed0e3f2e', 1, 'Green Lantern', 'PG-13', 'Movie', 'Test pilot Hal Jordan harnesses glowing new powers for good when he wears an otherworldly ring and helps an intergalactic force stop a powerful threat.'),
  ('6aecca89-0825-4402-9d14-b32f24465c92', 2, 'House Party', 'R', 'Movie', 'Grounded by his strict father, Kid risks life and limb to go to his best friend Play''s big bash but experiences one obstacle after another.'),
  ('1b2a5405-396f-48a8-90bf-0bd262755d53', 3, 'House Party 2', 'R', 'Movie', 'Kid goes off to college with scholarship money but when Play loses Kid''s tuition funds to a shady music promoter, they devise a wild plan to raise cash.'),
  ('70bdc810-7f89-4010-9df0-810b3aa0c403', 0, 'House Party 3', 'R', 'Movie', 'After Kid gets engaged, Play plans to throw the biggest bachelor party ever. But every celebration for these two always comes with complications.'),
  ('11bef89e-b8b5-4b9a-a67d-52d5a7aa63a6', 1, 'I Got the Hook Up', 'R', 'Movie', 'After getting their hands on a misdirected shipment of cell phones, two hustlers try to cash in by hawking the merchandise from the back of their van.'),
  ('1784fa1b-2b49-426e-ad9f-842fa4fdb062', 2, 'In Too Deep', 'R', 'Movie', 'Rookie cop Jeffrey Cole poses as a drug dealer to take down a crime lord and soon gets caught up in an underworld of bribery, intimidation and murder.'),
  ('159cd31c-8bce-4024-b403-963ca20f340c', 3, 'Initial D', 'PG-13', 'Movie', 'By day, an 18-year-old delivers tofu for his father, a retired race car driver; but by night, it''s the teen''s turn to take the wheel.'),
  ('8bfc020f-299d-4650-a008-89f1c6df562f', 0, 'Janoskians: Untold and Untrue', 'R', 'Movie', 'Follow the story of three Australian brothers and their two friends who became an international sensation by posting pranks and gags on YouTube.'),
  ('7de1ed08-9d68-49b6-932b-0b2032606f28', 1, 'Labyrinth', 'PG', 'Movie', 'In Jim Henson''s fantasy, teen Sarah embarks on a life-altering quest to rescue her little brother from the clutches of a treacherous goblin.'),
  ('abd1b3e4-2e4e-4c09-80fa-3dde66039d47', 2, 'Letters to Juliet', 'PG', 'Movie', 'By responding to a letter addressed to Shakespeare''s tragic heroine Juliet Capulet, an American woman in Verona, Italy, is led in search of romance.'),
  ('c2f79398-979a-4e54-b6ff-241aaca51418', 3, 'Level 16', 'PG-13', 'Movie', 'In a bleak academy that teaches girls the virtues of passivity, two students uncover the ghastly purpose behind their training and resolve to escape.'),
  ('d571dabb-f584-46e2-bd48-db2020582b59', 0, 'Love Don''t Cost a Thing', 'PG-13', 'Movie', 'A nerdy teen tries to make himself cool by association when he convinces a popular cheerleader to pose as his girlfriend.'),
  ('5df0c40e-5222-4a55-9d65-187cbb4e5073', 1, 'Love in a Puff', 'R', 'Movie', 'When the Hong Kong government enacts a ban on smoking cigarettes indoors, the new law drives hard-core smokers outside, facilitating unlikely connections.'),
  ('c4c73776-a0ba-4f0d-9f16-092d38a33362', 2, 'Mars Attacks!', 'PG-13', 'Movie', 'As flying saucers head for Earth, the president of the United States prepares to welcome alien visitors but soon learns they''re not coming in peace.'),
  ('322e40c9-2ef0-4d2f-91de-c3f149947631', 3, 'Marshall', 'PG-13', 'Movie', 'This biopic of Thurgood Marshall, the first Black U.S. Supreme Court justice, centers on his pivotal work in a sensational case as an NAACP lawyer.');
INSERT INTO catalog_title (title_id, minimum_tier_id, title_name, maturity_rating, content_type, synopsis) VALUES
  ('30dac735-b744-436e-939e-9f776cc90f63', 0, 'My Boss''s Daughter', 'R', 'Movie', 'A young man house-sits for his mean boss, hoping to use it as an opportunity to win the heart of the boss''s daughter, on whom he''s long had a crush.'),
  ('1fd304d5-25e8-444c-bf7d-d90a2a13bedf', 1, 'Mystery Men', 'PG-13', 'Movie', 'A team of far-from-super heroes try to earn respect by springing into action when brave and dashing Captain Amazing disappears.'),
  ('609ab480-e03b-47ed-9000-3adb9ea5f4af', 2, 'Once Upon a Time in America', 'R', 'Movie', 'Director Sergio Leone''s sprawling crime epic follows a group of Jewish mobsters who rise in the ranks of organized crime in 1920s New York City.'),
  ('5fb1448c-f256-4cf7-b980-b193f43fa30d', 3, 'Open Season 2', 'PG', 'Movie', 'Elliot the buck and his forest-dwelling cohorts must rescue their dachshund pal from some spoiled pets bent on returning him to domesticity.'),
  ('f61e38a8-8fe0-407b-8ee7-230b0f97e640', 0, 'Osmosis Jones', 'PG', 'Movie', 'Peter and Bobby Farrelly outdo themselves with this partially animated tale about an out-of-shape 40-year-old man who''s the host to various organisms.'),
  ('28d87e62-d438-4248-b55d-aee5a662a947', 1, 'Poseidon', 'PG-13', 'Movie', 'A tidal wave spells disaster for a ship of New Year''s Eve revelers when it capsizes the mammoth vessel, sending passengers into a battle for survival.'),
  ('a2af4cdd-d96f-4913-9691-3baccf2675fc', 2, 'Rhyme & Reason', 'R', 'Movie', 'The world and culture of rap song topics such as race, violence, police, family and sex are examined by hip-hop performers from both coasts.'),
  ('a3c195f9-75fa-41a1-a2af-da977fe6b6ea', 3, 'Same Kind of Different as Me', 'PG-13', 'Movie', 'A wealthy couple whose marriage is on the rocks befriends a local homeless man who changes their perspectives in this inspiring true story.'),
  ('47a06459-f189-4836-a941-755fd6b40f8c', 0, 'School of Rock', 'PG-13', 'Movie', 'Musician Dewey Finn gets a job as a fourth-grade substitute teacher, where he secretly begins teaching his students the finer points of rock ''n'' roll.'),
  ('af790ebc-39b7-4ff5-85bd-7e3b56ceef5a', 1, 'Snervous Tyler Oakley', 'PG-13', 'Movie', 'The inspiring Internet star and LGBT advocate shares an intimate view of his life and relationships during his international "Slumber Party" tour.'),
  ('2a696007-a3e1-40ee-81b8-8222fe9c0280', 2, 'Tears of the Sun', 'R', 'Movie', 'A Navy SEAL is sent to a war-torn African jungle to rescue a doctor, only to realize he must also save the refugees in the physician''s care.'),
  ('26821432-aba6-4c5d-92d3-02ece73618cb', 3, 'The Blue Lagoon', 'R', 'Movie', 'Two shipwrecked children, stranded for years on a deserted island, fall in love as teenagers and attempt to forge a life in the isolated paradise.'),
  ('33dd1582-2aaf-4350-aaef-e6197f9cf399', 0, 'The Golden Child', 'PG-13', 'Movie', 'A fast-talking L.A. social worker goes through a series of traps and terrors to find a kidnapped Tibetan child with mystical powers.'),
  ('e613850e-84b6-4b0c-9c0b-a43fce96e863', 1, 'The Guns of Navarone', 'PG-13', 'Movie', 'During World War II, British forces launch an attack designed to take out the massive Nazi cannons that guard a critical sea channel.'),
  ('e23e3496-3192-485c-9ffc-84c6bdf297ec', 2, 'The Interview', 'R', 'Movie', 'Seth Rogen and James Franco star in this provocative comedy about two journalists recruited by the CIA after they arrange an interview with Kim Jong-un.'),
  ('a9a58e76-baa5-4d1c-8878-a30bd432f124', 3, 'The Nutty Professor', 'PG-13', 'Movie', 'After being made fun of for his weight, a kind and brainy professor takes a dose of a revolutionary formula that changes more than just his appearance.'),
  ('1ee262d3-4591-40bd-b86f-c541ba954052', 0, 'The Nutty Professor II: The Klumps', 'PG-13', 'Movie', 'After getting engaged, Sherman Klump prepares for his big day. But his sinister alter ego Buddy Love threatens to ruin his wedding and reputation.'),
  ('47718d6a-36d4-4644-a72a-4189790e2d52', 1, 'Welcome Home Roscoe Jenkins', 'PG-13', 'Movie', 'R.J. travels to Georgia for his parents'' 50th anniversary. But after pompously flaunting his Hollywood lifestyle, he must examine what he''s become.'),
  ('abff52f7-02d7-48cc-b9e6-cef2a8981fa8', 2, 'In the Line of Fire', 'R', 'Movie', 'A twisted yet ingenious killer torments a veteran Secret Service agent who''s haunted by his failure years ago to save President John F. Kennedy.'),
  ('e19678cf-831d-4486-8520-c79aa3872920', 3, 'Untold: Crime & Penalties', 'R', 'Movie', 'They were the bad boys of hockey — a team bought by a man with mob ties, run by his 17-year-old son, and with a rep for being as violent as they were good.'),
  ('6037a25a-a093-4e6a-aef3-80aa3be47528', 0, '2 Alone in Paris', 'R', 'Movie', 'A bumbling Paris policeman is doggedly determined to capture the master thief that repeatedly eludes him, even when they''re the last two men on Earth.'),
  ('2d10f876-5f77-487e-8d4b-af9bbcb2a1a6', 1, 'Thimmarusu', 'PG-13', 'Movie', 'Eight years after a young man is framed for murder, an up-and-coming lawyer re-opens the case, beginning a tricky mission to find the real culprit.'),
  ('d3536ce6-09fd-40ba-b9be-d8db7b1c9512', 2, 'Wind River', 'R', 'Movie', 'A tracker with the U.S. Fish and Wildlife Service assists a rookie FBI agent who''s investigating a teen girl''s murder on a remote Wyoming reservation.'),
  ('154146b0-28e0-4718-84d5-97ffff7180c2', 3, 'C Kkompany', 'PG-13', 'Movie', 'Three broke friends pose as an underworld gang for extortion, but their plan takes on a life of its own when their phony company becomes famous.'),
  ('04071b92-8e41-467f-98ca-aa0814493bd7', 0, 'EMI: Liya Hai To Chukana Padega', 'PG-13', 'Movie', 'A bank hires an enigmatic and unorthodox debt collector to recover money from four borrowers who are unable to pay their loans.'),
  ('c79918b5-d118-4daf-abff-d251daeb31cf', 1, 'He''s All That', 'PG-13', 'Movie', 'An influencer specializing in makeovers bets she can transform an unpopular classmate into prom king in this remake of the teen classic "She''s All That."'),
  ('a6a80e74-d5ff-43d6-8a62-d42b993e610d', 2, 'Koi Aap Sa', 'PG-13', 'Movie', 'Star athlete Rohan has his eye on a beautiful art student. But when his best friend Simran experiences a crisis, he drops everything to help her.'),
  ('772b8298-c1a0-4fe7-9c47-ddbe2113c141', 3, 'Krishna Cottage', 'PG-13', 'Movie', 'True love is put to the test when another woman comes between a pair of star-crossed young lovers in this thriller.'),
  ('16b7e0ad-5a53-42c8-bd1e-6e104d2b4d17', 0, 'Kucch To Hai', 'PG-13', 'Movie', 'A student tries to steal a test from a teacher''s home, leaving him for dead after an accident. A string of murders may be the professor''s revenge.'),
  ('1064c271-6188-4e80-9f12-1c8ab63b007b', 1, 'Kyaa Kool Hai Hum', 'R', 'Movie', 'Longtime friends Rahul and Karan head to Mumbai intent on making their dreams come true, but both men are suddenly saddled with bad luck.'),
  ('2ea1ff5e-ecbf-41d5-a472-4ccedccf7028', 2, 'Kyaa Kool Hain Hum 3', 'R', 'Movie', 'When an unlikely porn actor falls for a woman outside the industry, he employs his co-stars as a stand-in traditional family to impress her father.'),
  ('c33b45ea-f923-4975-a043-88167dc8a53c', 3, 'Kyaa Super Kool Hain Hum', 'R', 'Movie', 'An aspiring actor and a struggling DJ team up to pursue the ladies they love and a diamond that rightfully belongs to their oversexed dog.'),
  ('c62fe184-10cf-4e15-a9ab-40ea85bf1d55', 0, 'Kyo Kii... Main Jhuth Nahin Bolta', 'PG-13', 'Movie', 'The life and career of a lawyer are thrown into chaos when his son''s wish magically renders him incapable of telling a lie.'),
  ('f76e2cfb-a844-488a-b99e-520788029cfa', 1, 'LSD: Love, Sex Aur Dhokha', 'R', 'Movie', 'This provocative drama examines how the voyeuristic nature of modern society affects three unusual couples in Northern India.'),
  ('7005aaf3-5f78-4d1f-9085-f663c0d66595', 2, 'Mission Istaanbul: Darr Ke Aagey Jeet Hai', 'PG-13', 'Movie', 'A television journalist makes a risky career move by accepting a job offer from a controversial Istanbul television station.'),
  ('88d02124-083f-48f6-b0a9-a8501ae9b72c', 3, 'Once Upon a Time in Mumbaai', 'PG-13', 'Movie', 'Mumbai''s top mob boss rules the underworld with honor and compassion, but his power-hungry protégé will shake up the world of organized crime.'),
  ('b6291924-79aa-439c-aa2c-509fcfe24ceb', 0, 'Once Upon a Time in Mumbai Dobaara!', 'PG-13', 'Movie', 'This turbulent sequel to Once Upon a Time in Mumbai carries on the saga of the gangland don Shoaib Khan, who continues pressing for more control.'),
  ('9044fa9a-4e2b-4ac5-956e-f7d7a093eba4', 1, 'Ragini MMS', 'R', 'Movie', 'A couple out to have a sensuous weekend at a house outside of Mumbai finds it rigged with surveillance cameras and occupied by an evil entity.'),
  ('18b4623a-87ab-43ff-bdd0-dd3c93001fc3', 2, 'Ragini MMS 2', 'R', 'Movie', 'The horror continues when Ragini''s video goes viral and a sleazy director decides to make a movie about the incident in the original house.'),
  ('2506aedf-e12b-4ad1-b694-227bb21dd3fb', 3, 'SAS: Rise of the Black Swan', 'R', 'Movie', 'A special forces operative traveling from London to Paris with his girlfriend takes action when armed, ruthless mercenaries seize control of their train.'),
  ('e0a20db7-3fd4-45d4-bf3a-da297ad2e009', 0, 'Shootout at Lokhandwala', 'R', 'Movie', 'Based on a true story, this action film follows an incident that stunned a nation in the early 1990s. In Mumbai, India, the notorious gangster Maya holds off veteran cop Khan and a force of more than 200 policemen in a six-hour bloody gunfight.'),
  ('df86f854-32c3-4f3c-9e9e-379e0fbe0489', 1, 'Shor In the City', 'PG-13', 'Movie', 'When three small-time Mumbai crooks steal a bag on a train, they find that it''s filled with weapons and realize that their lives may be in danger.'),
  ('49338270-dc8e-4102-a623-532d85a9d6cb', 2, 'The Dirty Picture', 'PG-13', 'Movie', 'After running away from home in search of movie stardom, a village girl rises to become a prominent sex symbol.'),
  ('01a5305a-1ee8-44e4-9cdf-077b9bfea68d', 3, 'Bob Ross: Happy Accidents, Betrayal & Greed', 'PG-13', 'Movie', 'Bob Ross brought joy to millions as the world’s most famous art instructor. But a battle for his business empire cast a shadow over his happy trees.'),
  ('8831ea34-8846-4050-8052-a02222d95303', 0, 'Really Love', 'R', 'Movie', 'A rising Black painter tries to break into a competitive art world while balancing an unexpected romance with an ambitious law student.'),
  ('bf91f283-fc86-426c-b4a7-59eb88e70597', 1, 'The November Man', 'R', 'Movie', 'An ex-CIA agent emerges from retirement to protect an important witness, but he soon discovers that old friends can make the most dangerous enemies.'),
  ('9a16e871-2b24-402c-b211-9b1b25f2486b', 2, 'The Old Ways', 'R', 'Movie', 'A reporter visits her birthplace in Veracruz for a story about tribal culture, only to be kidnapped by locals who believe she''s demonically possessed.'),
  ('9ec9c3be-9f93-4b1f-8381-4f2164129c73', 3, 'The River Runner', 'R', 'Movie', 'In this documentary, a kayaker sets out to become the first man to paddle the four great rivers that flow from Tibet''s sacred Mount Kailash.'),
  ('67ef7f05-ca11-450b-9c10-5c5e64bd2093', 0, 'The Water Man', 'PG', 'Movie', 'Desperate to save his ailing mother, 11-year-old Gunner runs away from home on a quest to find a mythic figure rumored to have the power to cheat death.'),
  ('45cb14b0-8be3-47cb-ac43-4770c7728520', 1, 'Count Me In', 'R', 'Movie', 'This documentary features some of rock''s greatest drummers as they come together in an inspiring rhythmic journey about the power of human connection.');
INSERT INTO catalog_title (title_id, minimum_tier_id, title_name, maturity_rating, content_type, synopsis) VALUES
  ('a92d77fd-5c81-4ca6-ae39-a4b2a93d517f', 2, 'Untold: Caitlyn Jenner', 'PG', 'Movie', 'Caitlyn Jenner''s unlikely path to Olympic glory was inspirational. But her more challenging road to embracing her true self proved even more meaningful.'),
  ('678f4e88-7ef2-4b7a-b0d2-baca3f5e3d3d', 3, 'Boomika', 'PG-13', 'Movie', 'Paranormal activity at a lush, abandoned property alarms a group eager to redevelop the site, but the eerie events may not be as unearthly as they think.'),
  ('b8404c1b-1938-4037-b04a-a056cf58a92a', 0, 'Boomika (Hindi)', 'PG-13', 'Movie', 'Paranormal activity at a lush, abandoned property alarms a group eager to redevelop the site, but the eerie events may not be as unearthly as they think.'),
  ('0f91b001-4933-4562-89e2-ab259f26cf86', 1, 'Boomika (Malayalam)', 'PG-13', 'Movie', 'Paranormal activity at a lush, abandoned property alarms a group eager to redevelop the site, but the eerie events may not be as unearthly as they think.'),
  ('20c71117-e51c-4915-8a12-e24dc6de7e0e', 2, 'Boomika (Telugu)', 'PG-13', 'Movie', 'Paranormal activity at a lush, abandoned property alarms a group eager to redevelop the site, but the eerie events may not be as unearthly as they think.'),
  ('125d769d-864a-4e7b-a65f-10df0ca818d1', 3, 'The Witcher: Nightmare of the Wolf', 'R', 'Movie', 'Escaping from poverty to become a witcher, Vesemir slays monsters for coin and glory, but when a new menace rises, he must face the demons of his past.'),
  ('c619aa46-8c46-42bd-ab50-accc5049a366', 0, 'Gunshot', 'PG-13', 'Movie', 'After a clash at a protest ends in bloodshed, a forensic doctor and a journalist embark on a search for the elusive truth.'),
  ('5e0cb418-0063-4ff8-9a6d-333097666ac3', 1, 'Man in Love', 'R', 'Movie', 'When he meets a debt-ridden woman who''s caring for her ailing father, a debt collector with a heart of gold sets out to win her love.'),
  ('eb767d3e-90a3-4425-a714-372cec26ad2b', 2, 'Sweet Girl', 'R', 'Movie', 'He lost the love of his life to a pharmaceutical company''s greed. Now his daughter is without a mother, and he''s without justice. For now.'),
  ('62f79e6f-930e-48ae-9d48-ba4f95f3913b', 3, 'The Loud House Movie', 'G', 'Movie', 'With his parents and all 10 sisters in tow, Lincoln Loud heads to Scotland and learns that royalty runs in the family in this global musical journey!'),
  ('c12881e2-2c38-4204-a382-486fc5352cc2', 0, 'A Faraway Land', 'PG', 'Movie', 'In the Faroe Islands, a married woman meets a reporter filming a documentary on overseas Filipino workers, which soon sparks a complicated love story.'),
  ('f650fe35-da3a-4f98-81c4-a5ace32e73c7', 1, 'Like Crazy', 'PG-13', 'Movie', 'A spirited exchange student and an American man fall in love in LA. But their romance faces an uphill battle when she is forced to return to England.'),
  ('197dc496-278f-4134-b9b9-ad0c86ca7d8d', 2, 'Black Island', 'R', 'Movie', 'The dark secrets of a seemingly peaceful island threaten to swallow up an orphaned student when he grows close to a mysterious new teacher.'),
  ('d2e32775-206e-4ac2-b049-06234bf79d93', 3, 'Bombay', 'PG-13', 'Movie', 'Years after they elope against their family’s wishes, a couple and their sons become caught in the throes of conflict in their city.'),
  ('05896439-84d4-40b1-a743-5f1df5bb6c4e', 0, 'Memories of a Murderer: The Nilsen Tapes', 'R', 'Movie', 'Serial killer Dennis Nilsen narrates his life and horrific crimes via a series of chilling audiotapes recorded from his jail cell.'),
  ('6fd8c0e8-3c8c-4d7d-a3f6-b42dbc7e170c', 1, 'Nneka The Pretty Serpent', 'PG-13', 'Movie', 'Years after the mysterious murder of her parents, a traumatized woman gains supernatural powers that aid in her quest for revenge against the killers.'),
  ('13b68ca7-6a65-4ca0-b5f0-75b1c2691c2b', 2, 'O Kadhal Kanmani', 'PG-13', 'Movie', 'It''s love at first sight for a young couple repelled by the concept of marriage, but their view shifts when they meet their older-couple neighbors.'),
  ('6165a454-222b-4675-a78d-db081ff9aca0', 3, 'Out of my league', 'R', 'Movie', 'Tired of swiping through the dating scene with her besties in tow, a charming yet awkward woman with a rare genetic disorder sets her sights on love.'),
  ('59251681-024e-479f-8a54-8f585fc4cba8', 0, 'Pahuna', 'PG', 'Movie', 'Fleeing unrest in their native Nepal, three young siblings separated from their parents must beat the odds to survive on their own in India.'),
  ('e1ead439-7a6d-43c4-81b6-cc6aa596d2d4', 1, 'The Secret Diary of an Exchange Student', 'PG-13', 'Movie', 'Looking to shake things up, two best friends embark on a life-changing adventure abroad as exchange students. But can they stay out of trouble?'),
  ('65554b74-12e2-4d9c-a22b-b814b59b64a2', 2, 'Untold: Deal With the Devil', 'R', 'Movie', 'Christy Martin broke boundaries and noses as she rose in the boxing world, but her public persona belied personal demons, abuse and a threat on her life.'),
  ('d43d999f-9de5-472e-9472-c5ab84005aa9', 3, 'Walk of Shame', 'R', 'Movie', 'After a night of boozy carousing, a local newscaster finds herself stranded on the streets of LA just hours before the job interview of a lifetime.'),
  ('4f0bdc3b-f598-488b-97f4-afcbec879930', 0, 'The Piano', 'R', 'Movie', 'With her daughter and her beloved piano in tow, a mute Scottish woman arrives in New Zealand, where a gruff loner sets out to seduce her.'),
  ('f6c9dc35-970e-466f-8c01-cab054a05600', 1, 'Unroyal', 'R', 'Movie', 'When a rude and arrogant princess finds herself relying on a gatekeeper after a terrible accident, it may be enough to make her change her ways.'),
  ('d3f594ce-4451-4df2-8715-edd2a48d47a1', 2, 'Beckett', 'R', 'Movie', 'An American tourist goes on the run in Greece after a tragic accident plunges him into a political conspiracy that makes him a target for assassination.'),
  ('cb040027-4867-432e-a253-47be82e9b945', 3, 'Lokillo: Nothing''s the Same', 'R', 'Movie', 'Through songs and puns, comedian Lokillo Florez hilariously reviews how Latin Americans have adjusted to a new world where no-hugging policies prevail.'),
  ('4a2dcc84-d8a8-4960-bac9-2db0972f5e9a', 0, 'Monster Hunter: Legends of the Guild', 'PG', 'Movie', 'In a world where humans and fearsome monsters live in an uneasy balance, young hunter Aiden fights to save his village from destruction by a dragon.'),
  ('13464b55-0a0b-4ab8-9610-7089615d1e05', 1, 'Brother Jekwu', 'PG-13', 'Movie', 'Chasing wild success, a village hustler follows his cousin from Nigeria to Kenya and stumbles into the shady business affairs of a notorious overlord.'),
  ('f5400aca-5d29-424b-8dc0-b4faf4c6a0c1', 2, 'La diosa del asfalto', 'R', 'Movie', 'A woman from a tough neighborhood outside Mexico City comes home a rock star, inadvertently provoking a confrontation with the ghosts of her past.'),
  ('151f0b36-0479-4f54-87df-ad5a491a43d2', 3, 'Misha and the Wolves', 'PG-13', 'Movie', 'As a little girl, she escaped the Holocaust and lived among wolves. Or did she? An extraordinary story elicits sympathy — then draws scrutiny.'),
  ('b62b8990-f8b9-4873-955a-62b2f76d0acc', 0, 'The Kissing Booth 3', 'PG-13', 'Movie', 'Determined to make the most of her final summer before college, Elle plans the ultimate bucket list as she navigates what comes next with Noah and Lee.'),
  ('eab52303-98f9-40f5-bdd8-a72635dc6c08', 1, 'The Railway Man', 'R', 'Movie', 'Decades after World War II, a still-shattered soldier unexpectedly falls in love and sees a bizarre coincidence bring his past back into focus.'),
  ('0db7cf97-e1e9-4ee0-852b-d30fb6336378', 2, 'Untold: Malice at the Palace', 'R', 'Movie', 'Key figures from an infamous 2004 incident between players and fans at an NBA game in Michigan discuss the fight, its fallout and its lasting legacy.'),
  ('65d7e21b-2ec6-4190-a13a-79b39963c06f', 3, 'Quartet', 'PG-13', 'Movie', 'To save their posh retirement home, former opera stars plan a gala recital — until the biggest diva among them refuses to sing.'),
  ('4707fc02-c8f4-435c-8402-c40f3c12a53d', 0, 'Slay', 'R', 'Movie', 'In pursuit of both success and validation, a group of tech-savvy individuals juggle intimate encounters, first impressions and romantic opportunities.'),
  ('51afa3b2-a11c-4d0f-b19f-c6de64a513aa', 1, 'Takizawa Kabuki ZERO 2020 The Movie', 'PG', 'Movie', 'Superstar Hideaki Takizawa reimagines his acclaimed kabuki production for the screen, featuring the dynamic talents of idol group Snow Man.'),
  ('30a1eb71-75de-41d7-9762-64042cfae5c7', 2, 'The Paper Tigers', 'PG-13', 'Movie', 'After reuniting as middle-aged men, three kung-fu prodigies must set their differences aside and dust off their skills to avenge their beloved mentor.'),
  ('faa36d0f-c1d7-4724-89f1-7e8a9a53d979', 3, 'Quam''s Money', 'R', 'Movie', 'In this sequel to "New Money," Quam, a security guard turned multimillionaire, lives the good life with his fortune until he falls victim to fraud.'),
  ('69ccaaf1-3b3f-460a-b800-8bc8f5a76c98', 0, 'The Swarm', 'PG-13', 'Movie', 'A single mother breeds locusts as high-protein food, but has trouble getting them to reproduce — until she finds they have a taste for blood.'),
  ('e205fcff-6c35-46c8-bde4-006f5ea69083', 1, 'Vivo', 'PG', 'Movie', 'A music-loving kinkajou embarks on the journey of a lifetime to fulfill his destiny and deliver a love song for an old friend.'),
  ('24b9bde9-f595-4f7e-b79c-1efb7c2caf1f', 2, 'Chennai Express', 'PG-13', 'Movie', 'What could have been a sad journey turns joyful for Rahul when he falls in love with a woman en route to submerging his grandfather''s ashes.'),
  ('66b9ac0d-ac61-449b-9170-374655088bf9', 3, 'City of God: 10 Years Later', 'R', 'Movie', 'A decade after the seminal Brazilian film "City of God," this documentary reunites some of the cast and crew to find out what paths their lives took.'),
  ('2b2494c8-b028-4514-b683-2a592d4b0635', 0, 'Esperando la carroza', 'R', 'Movie', 'Cora has three sons and a daughter and she´s almost 80. One day during a family reunion the big question comes up: who will be her heir?'),
  ('c9bf056f-2aff-40c5-ac70-bb2523b35b42', 1, 'Lady Boss: The Jackie Collins Story', 'PG-13', 'Movie', '"Queen of Sleaze" or feminist pioneer? Powerhouse novelist Jackie Collins created a brash sex-positive persona while hiding her private struggles.'),
  ('ac3a2c5d-ce73-4f91-8052-1a6308eed8dc', 2, 'Tango Feroz', 'R', 'Movie', 'One of the first rock stars in Argentina, Tango leads a full life during an era of social unrest – one of both glory and despair.'),
  ('c506eb98-7e74-450a-acef-146d7f7b4adb', 3, '''76', 'PG', 'Movie', 'When her husband is accused of taking part in an attempted military coup, a pregnant woman''s life takes an emotional turn. Inspired by true events.'),
  ('ceaa1fa0-225f-4bb2-9173-5a501bd8877f', 0, 'Aftermath', 'R', 'Movie', 'Desperate to save their marriage, a young couple takes a deal and moves into their dream home, but disturbing events reveal the house''s troubled history.'),
  ('94a6456c-8e69-4a79-a3f4-bc15717397ff', 1, 'American Masters: Inventing David Geffen', 'R', 'Movie', 'The son of Jewish immigrants, David Geffen emerged from a humble upbringing to become one of the most powerful media personalities in America.'),
  ('7bfc8d38-a0f2-4e95-bc73-af8d278462c4', 2, 'Heavy', 'R', 'Movie', 'Overweight Victor hides from the world making pizzas in his mother''s gloomy dive until a new waitress blows in and disrupts his isolation.'),
  ('6a392e82-fcc6-4c5b-94d0-43e8d43b2ee8', 3, 'Ije: The Journey', 'R', 'Movie', 'When her sister is accused of multiple murders, a Nigerian woman travels to Los Angeles to uncover the truth and fight for her sibling’s freedom.');
INSERT INTO catalog_title (title_id, minimum_tier_id, title_name, maturity_rating, content_type, synopsis) VALUES
  ('5f574f2b-0e78-4a24-9613-7f832e27d74e', 0, 'Pray Away', 'PG-13', 'Movie', 'Ex-leaders and a survivor of the so-called "conversion therapy" movement speak out about its harm to the LGBTQ+ community and its devastating persistence.'),
  ('bddf17a3-8998-492c-8912-803fd47fe655', 1, 'Shiny_Flakes: The Teenage Drug Lord', 'R', 'Movie', 'Max S. reveals how he built a drug empire from his childhood bedroom in this story that inspired the series "How to Sell Drugs Online (Fast)."'),
  ('fca1e288-6dc3-43d8-818b-a29044878ec9', 2, 'Beethoven', 'PG', 'Movie', 'A father reluctantly agrees to let his children keep a St. Bernard puppy, but the playful pooch soon turns into a full-grown engine of destruction.'),
  ('48068137-d71e-4e49-af92-4365877ae876', 3, 'Beethoven''s 2nd', 'PG', 'Movie', 'After St. Bernard Beethoven sires a brood with Missy, he and the Newton kids must intervene when Missy''s owner tries to sell the puppies.'),
  ('667520cd-edf4-44c1-b8ff-01b435ac5279', 0, 'Beowulf', 'PG-13', 'Movie', 'This deftly animated take on a legendary Old English epic tells the timeless tale of a Scandinavian hero who''s known for slaying dragons.'),
  ('603ddf66-b0ce-4f6f-8570-6d8b46cbdf5e', 1, 'Boyka: Undisputed', 'R', 'Movie', 'The fourth film in the action franchise finds Boyka taking on brutal gangsters to protect the widow of a man he unintentionally killed in the ring.'),
  ('eec26066-804b-4f9c-a39c-cbd9a0440eb2', 2, 'Catch Me If You Can', 'PG-13', 'Movie', 'An FBI agent makes it his mission to put cunning con man Frank Abagnale Jr. behind bars. But Frank not only eludes capture, he revels in the pursuit.'),
  ('25bd96db-d487-48b0-9ae6-9ee32cab5bbe', 3, 'Cloudy with a Chance of Meatballs', 'PG', 'Movie', 'When inventor Flint Lockwood makes clouds rain food, the citizens of Chewandswallow can feed themselves. But a bowl of disaster is about to overflow.'),
  ('a01d2da1-b9d5-4f31-a24b-8d17f3bc0556', 0, 'Deep Blue Sea', 'R', 'Movie', 'Scientists conduct research on sharks in search of an Alzheimer''s cure. But a dangerous shortcut leads to huge sharks with near-human intelligence.'),
  ('b1e1f9b3-5d65-4a03-8b38-095d6f086a29', 1, 'Ferris Bueller''s Day Off', 'PG-13', 'Movie', 'After faking an illness to skip school, popular teen Ferris Bueller enjoys a fun-filled day in Chicago with his girlfriend and his uptight best friend.'),
  ('b8b9e7ef-9795-40ca-9938-dc4209e95331', 2, 'Five Feet Apart', 'PG-13', 'Movie', 'A teen with cystic fibrosis shakes up her daily routine and challenges hospital protocol when she falls for a fellow patient.'),
  ('28e0daaf-2d57-4fdf-964b-cc2a4b1140a4', 3, 'Freedomland', 'R', 'Movie', 'When a woman reports that her infant son was kidnapped by a black man, an African American detective and a white activist team up to dig for details.'),
  ('80044133-2daa-4e82-9887-822867351fbd', 0, 'Good Luck Chuck', 'R', 'Movie', 'Every time Chuck breaks up with a girlfriend, she ends up engaged to her next boyfriend. Soon, women are dating Chuck in hopes of meeting Mr. Right.'),
  ('a1ee2dff-19ae-4432-9bd2-fd518ae3081d', 1, 'I missed you: Director''s Cut', 'PG-13', 'Movie', 'A workaholic reconnects with two men she blocked on social media five years ago and begins to reflect on her past life choices.'),
  ('4330fb4f-9674-420e-adab-a6f416420246', 2, 'Inception', 'PG-13', 'Movie', 'A troubled thief who extracts secrets from people''s dreams takes one last job: leading a dangerous mission to plant an idea in a target''s subconscious.'),
  ('e4b1bfb5-38ae-4a4f-81d3-b6df87a36322', 3, 'Magnolia', 'R', 'Movie', 'Through chance, history and divine intervention, a cast of eclectic characters weaves and warps through each other''s lives on a random day in California.'),
  ('4be22d06-e9c3-4c69-a509-ee3858fe3070', 0, 'Major Payne', 'PG-13', 'Movie', 'A hardened Marine is given his marching orders and must now lead a disorderly group of mismatched cadets into a junior ROTC competition.'),
  ('c8784fc8-269e-4150-92b5-c3620b0bd5a2', 1, 'My Girl', 'PG-13', 'Movie', 'This coming-of-age charmer follows a summer in the life of an 11-year-old girl who learns about love and loss as she grapples with profound changes.'),
  ('49cb3b2a-f9fe-41d5-954d-133d33f1e1a3', 2, 'My Girl 2', 'PG', 'Movie', 'A teen makes surprising discoveries when she talks to her dead mother''s high school friends for an essay about someone she admires but has never met.'),
  ('84e1979f-d2fd-4e60-af81-5b42e05dfd92', 3, 'Open Season: Scared Silly', 'PG', 'Movie', 'When a spooky werewolf tale scares Boog out of joining the annual camping trip, his friends hatch a plan to cure him of his fear.'),
  ('373641ee-93c2-4722-9cd1-fd87c8526778', 0, 'Pineapple Express', 'R', 'Movie', 'After witnessing a murder, a perpetually stoned process server and his good-natured dealer go on the run from a drug lord who''s out to kill them.'),
  ('f6defc35-114c-4ba1-b699-6b558c46f370', 1, 'Planet 51', 'PG', 'Movie', 'After landing on a planet reminiscent of 1950s suburbia, a human astronaut tries to avoid capture, recover his spaceship and make it home safely.'),
  ('633d4a8e-384c-4d2e-aaed-54c84b64d5ea', 2, 'Poms', 'PG-13', 'Movie', 'After moving to a retirement community, loner Martha befriends a fun-loving neighbor and forms a cheerleading club for young-at-heart seniors.'),
  ('eee658aa-e116-4dca-a9b4-546bbaaf8d36', 3, 'Seabiscuit', 'PG-13', 'Movie', 'An ungainly-looking colt becomes a winning thoroughbred in this Depression-era drama based on the true story of champion racehorse Seabiscuit.'),
  ('44bce0b2-ebe1-4391-913a-eac3d6f93270', 0, 'Space Cowboys', 'PG-13', 'Movie', 'A retired engineer agrees to help NASA prevent a Russian satellite from falling to Earth if he and his over-the-hill pals can man the mission.'),
  ('b5e47843-8cf2-4bcc-b439-25303097f865', 1, 'Team America: World Police', 'R', 'Movie', 'In this musical satire, an all-marionette police force takes on the challenging role of keeping the peace on a troubled planet.'),
  ('ac3d5b79-0453-45d6-b1c3-4c0202aef2a7', 2, 'The Edge of Seventeen', 'R', 'Movie', 'A troubled teenager finds high school life even less bearable after she catches her childhood best friend hooking up with her popular older brother.'),
  ('7ff6a8c9-d08f-482e-b25a-959bb0e3ca5b', 3, 'The Haunting in Connecticut 2: Ghosts of Georgia', 'R', 'Movie', 'A couple''s Georgia dream home becomes a living nightmare when their daughter begins to have frightening visions from the property''s terrible past.'),
  ('ab0a3575-3507-41ee-a79d-6d96b0ccfea6', 0, 'The Last Boy Scout', 'R', 'Movie', 'Private eye Joe Hallenbeck is forced to team up with a disgraced quarterback to uncover a conspiracy by a politician and a football team owner.'),
  ('bd7acfc0-80a1-46b2-bd6b-178ccbdf960f', 1, 'The Lincoln Lawyer', 'R', 'Movie', 'A street-wise defense lawyer who operates out of the back seat of his Lincoln lands a high-profile case that soon puts him and his family in danger.'),
  ('30c70b00-6277-4ffe-9e24-df0307f74834', 2, 'The Losers', 'PG-13', 'Movie', 'After a search-and-destroy mission leads to betrayal, an elite black ops squad seeks revenge. But they must remain deep undercover to even the score.'),
  ('baf8b090-ec17-4baf-95f7-436ad9e77882', 3, 'The Machinist', 'R', 'Movie', 'Haunted and gaunt after a prolonged bout of insomnia, factory worker Trevor Reznik begins to question his sanity amid a series of mysterious events.'),
  ('c507b879-b52c-4fcd-a6a9-1581aaacd4c0', 0, 'The Net', 'PG-13', 'Movie', 'A computer analyst becomes a target after she stumbles onto a conspiracy via a mysterious floppy disk, forcing her to go on the run to clear her name.'),
  ('5f253a4c-eae9-46bb-ae71-97ad98a9a312', 1, 'Blood & Water', 'R', 'Series', 'After crossing paths at a party, a Cape Town teen sets out to prove whether a private-school swimming star is her sister who was abducted at birth.'),
  ('492fee42-2502-40b6-b0bf-edbb83270e74', 2, 'Ganglands', 'R', 'Series', 'To protect his family from a powerful drug lord, skilled thief Mehdi and his expert team of robbers are pulled into a violent and deadly turf war.'),
  ('4fecfd1f-168d-4b6b-9da0-2f9a8625dbf4', 3, 'Jailbirds New Orleans', 'R', 'Series', 'Feuds, flirtations and toilet talk go down among the incarcerated women at the Orleans Justice Center in New Orleans on this gritty reality series.'),
  ('8289e8f1-3b7c-4bb8-97ec-902a1aa225ea', 0, 'Kota Factory', 'R', 'Series', 'In a city of coaching centers known to train India’s finest collegiate minds, an earnest but unexceptional student and his friends navigate campus life.'),
  ('ada2f6ce-f1cb-4a35-bbab-def79623df1f', 1, 'Midnight Mass', 'R', 'Series', 'The arrival of a charismatic young priest brings glorious miracles, ominous mysteries and renewed religious fervor to a dying town desperate to believe.'),
  ('e5ee0105-ba51-4e0f-8548-3c49a8f51d79', 2, 'The Great British Baking Show', 'PG-13', 'Series', 'A talented batch of amateur bakers face off in a 10-week competition, whipping up their best dishes in the hopes of being named the U.K.''s best.'),
  ('5d987eda-4fd5-4692-bb5f-29931efc27c2', 3, 'Vendetta: Truth, Lies and The Mafia', 'R', 'Series', 'Sicily boasts a bold "Anti-Mafia" coalition. But what happens when those trying to bring down organized crime are accused of being criminals themselves?'),
  ('0657a82c-0aec-42d2-9b4f-8019ffaffc1c', 0, 'Bangkok Breaking', 'R', 'Series', 'Struggling to earn a living in Bangkok, a man joins an emergency rescue service and realizes he must unravel a citywide conspiracy.'),
  ('53b8ff8b-6234-4bb7-802b-562d112808ae', 1, 'Crime Stories: India Detectives', 'R', 'Series', 'Cameras following Bengaluru police on the job offer a rare glimpse into the complex and challenging inner workings of four major crime investigations.'),
  ('112116c7-1a74-4a9a-9cae-ef883a4b81c1', 2, 'Dear White People', 'R', 'Series', 'Students of color navigate the daily slights and slippery politics of life at an Ivy League college that''s not nearly as "post-racial" as it thinks.'),
  ('ab5faf4d-ddd0-42e9-99f8-d16dfcb7aee3', 3, 'Falsa identidad', 'R', 'Series', 'Strangers Diego and Isabel flee their home in Mexico and pretend to be a married couple to escape his drug-dealing enemies and her abusive husband.'),
  ('fdcb8ea6-9c4e-43ed-94fe-b88e96b5d2bb', 0, 'Jaguar', 'R', 'Series', 'In the 1960s, a Holocaust survivor joins a group of self-trained spies who seek justice against Nazis fleeing to Spain to hide after WWII.'),
  ('5e8ee526-39ba-47df-a532-71e13a837570', 1, 'Monsters Inside: The 24 Faces of Billy Milligan', 'PG-13', 'Series', 'In the late 1970s, an accused serial rapist claims multiple personalities control his behavior, setting off a legal odyssey that captivates America.'),
  ('6e2715d2-a58c-4a29-a0df-bfedaafdf386', 2, 'Resurrection: Ertugrul', 'PG-13', 'Series', 'When a good deed unwittingly endangers his clan, a 13th-century Turkish warrior agrees to fight a sultan''s enemies in exchange for new tribal land.'),
  ('24a1c825-0b58-4217-aecf-cf03ea603929', 3, 'Love on the Spectrum', 'PG-13', 'Series', 'Finding love can be hard for anyone. For young adults on the autism spectrum, exploring the unpredictable world of dating is even more complicated.'),
  ('67538e22-7044-4095-8c5e-f5ba8284a116', 0, 'Chicago Party Aunt', 'R', 'Series', 'Chicago Party Aunt Diane is an idolized troublemaker with a talent for avoiding adulthood — and a soft spot for her soul-searching nephew.'),
  ('e2edae90-3285-4ad9-8e81-7a5d848d648f', 1, 'Sex Education', 'R', 'Series', 'Insecure Otis has all the answers when it comes to sex advice, thanks to his therapist mom. So rebel Maeve proposes a school sex-therapy clinic.');
INSERT INTO catalog_title (title_id, minimum_tier_id, title_name, maturity_rating, content_type, synopsis) VALUES
  ('03f8f61f-ba2b-44e7-8172-622a47a63251', 2, 'Squid Game', 'R', 'Series', 'Hundreds of cash-strapped players accept a strange invitation to compete in children''s games. Inside, a tempting prize awaits — with deadly high stakes.'),
  ('c61236bc-21be-4f1f-a720-a7834757fbdf', 3, 'Tayo and Little Wizards', 'G', 'Series', 'Tayo speeds into an adventure when his friends get kidnapped by evil magicians invading their city in search of a magical gemstone.'),
  ('27af14a4-1b1a-4bb1-94cc-3c532d8d9f10', 0, 'Angry Birds', 'G', 'Series', 'Birds Red, Chuck and their feathered friends have lots of adventures while guarding eggs in their nest that pesky pigs keep trying to steal.'),
  ('9f51ed87-d384-4df4-af61-14d6c16eb7eb', 1, 'Chhota Bheem', 'G', 'Series', 'A brave, energetic little boy with superhuman powers leads his friends on exciting adventures to guard their fellow Dholakpur villagers from evil.'),
  ('3a29d756-b24b-4234-978d-4f610c5b02d6', 2, 'He-Man and the Masters of the Universe', 'G', 'Series', 'Mighty teen Adam and his heroic squad of misfits discover the legendary power of Grayskull — and their destiny to defend Eternia from sinister Skeletor.'),
  ('c25dae68-1b0d-415a-a953-2efdd1bc8bc9', 3, 'The Smart Money Woman', 'R', 'Series', 'Five glamorous millennials strive for success as they juggle careers, finances, love and friendships. Based on Arese Ugwu''s 2016 best-selling novel.'),
  ('08eba9a7-5b3d-4726-88d7-c615134a20de', 0, 'Castle and Castle', 'R', 'Series', 'A pair of high-powered, successful lawyers find themselves defending opposite interests of the justice system, causing a strain on their happy marriage.'),
  ('24085cbb-225a-424f-b89c-2474fb963a28', 1, 'Dharmakshetra', 'PG', 'Series', 'After the ancient Great War, the god Chitragupta oversees a trial to determine who were the battle''s true heroes and villains.'),
  ('a21e6b09-c414-4b75-9cbb-08a367652a66', 2, 'Nailed It', 'PG', 'Series', 'Home bakers with a terrible track record take a crack at re-creating edible masterpieces for a $10,000 prize. It''s part reality contest, part hot mess.'),
  ('d4f34ec2-394e-429a-9622-4dc8c270a90b', 3, 'Numberblocks', 'G', 'Series', 'In a place called Numberland, math adds up to tons of fun when a group of cheerful blocks work, play and sing together.'),
  ('ca217769-1ffb-4efa-a527-c8cdeaac1c4e', 0, 'Raja Rasoi Aur Anya Kahaniyan', 'G', 'Series', 'Explore the history and flavors of regional Indian cuisine, from traditional Kashmiri feasts to the vegetarian dishes of Gujarat.'),
  ('f3835838-3405-4867-ad16-49d237accbbb', 1, 'Saved by the Bell', 'PG', 'Series', 'From middle school to college, best friends Zack, Kelly, Slater, Jessie, Screech and Lisa take on the highs and lows of life together in this hit series.'),
  ('724e7fd1-a793-45f7-a91d-0c01d1e1eaeb', 2, 'Stories by Rabindranath Tagore', 'PG', 'Series', 'The writings of Nobel Prize winner Rabindranath Tagore come to life in this collection of tales set in early-20th-century Bengal.'),
  ('dffc20b1-d469-41e8-8085-e17487964488', 3, 'Too Hot To Handle: Latino', 'R', 'Series', 'On this reality show, singles from Latin America and Spain are challenged to give up sex. But here, abstinence comes with a silver lining: US$100,000.'),
  ('62e828ec-7ec1-427e-8483-7dfb12203e65', 0, 'Jack Whitehall: Travels with My Father', 'R', 'Series', 'Jovial comic Jack Whitehall invites his stuffy father, Michael, to travel with him through Southeast Asia in an attempt to strengthen their bond.'),
  ('7b19db42-d9af-4db2-be62-619e92f783f7', 1, 'The World''s Most Amazing Vacation Rentals', 'PG', 'Series', 'With an eye for every budget, three travelers visit vacation rentals around the globe and share their expert tips and tricks in this reality series.'),
  ('801965b9-0e3e-462c-86fc-b6618aa40858', 2, 'Yowamushi Pedal', 'PG-13', 'Series', 'A timid, anime-loving teen gets drawn into a school cycling club, where his new friends help him face tough challenges to develop his racing talent.'),
  ('ab7d99ce-5345-4e96-8863-a59cc3571104', 3, 'Lucifer', 'PG-13', 'Series', 'Bored with being the Lord of Hell, the devil relocates to Los Angeles, where he opens a nightclub and forms a connection with a homicide detective.'),
  ('31b38ccf-b4dc-4bd0-8b5d-edabaf282198', 0, 'Metal Shop Masters', 'R', 'Series', 'On this competition show, a group of metal artists torch, cut and weld epic, badass creations from hardened steel. Only one will win a $50,000 prize.'),
  ('b56e92c0-336a-4d28-94d6-f55ddffefb4e', 1, 'Pokémon Master Journeys: The Series', 'G', 'Series', 'As Ash battles his way through the World Coronation Series, Goh continues his quest to catch every Pokémon. Together, they''re on a journey to adventure!'),
  ('bcc1dc8c-f65f-41c9-8e1c-e9070ce7746f', 2, 'Titipo Titipo', 'G', 'Series', 'Titipo the train is out to prove that he''s got what it takes to help the folks of Train Village ride the rails safely and reliably.'),
  ('6199fb65-c6ce-445c-8231-7b6ae323ddab', 3, 'Mighty Raju', 'G', 'Series', 'Born with superhuman abilities, young Raju wants to use his powers to make the world a better place — but that will mean facing plenty of challenges!'),
  ('45744c1f-e3fd-40d4-b2f5-914622dd5694', 0, 'Into the Night', 'R', 'Series', 'Passengers and crew aboard a hijacked overnight flight scramble to outrace the sun as a mysterious cosmic event wreaks havoc on the world below.'),
  ('394d843e-4690-441a-9e54-5b4760a1a27a', 1, 'The Circle', 'R', 'Series', 'Status and strategy collide in this social experiment and competition show where online players flirt, befriend and catfish their way toward $100,000.'),
  ('457f05e8-60ab-46fb-a59a-d0aefd29b380', 2, 'Kid Cosmic', 'G', 'Series', 'A boy''s superhero dreams come true when he finds five powerful cosmic stones. But saving the day is harder than he imagined — and he can''t do it alone.'),
  ('ee41c7fa-d0fb-4bbe-b133-6759a9fdd663', 3, 'Octonauts: Above & Beyond', 'G', 'Series', 'The Octonauts expand their exploration beyond the sea — and onto land! With new rides and new friends, they''ll protect any habitats and animals at risk.'),
  ('410157e3-ab12-4fad-8525-c7e5bbbbbe45', 0, 'On the Verge', 'R', 'Series', 'Four women — a chef, a single mom, an heiress and a job seeker — dig into love and work, with a generous side of midlife crises, in pre-pandemic LA.'),
  ('4b90fdad-a7c1-4394-b4a9-24cd33379460', 1, 'Tobot Galaxy Detectives', 'G', 'Series', 'An intergalactic device transforms toy cars into robots: the Tobots! Working with friends to solve mysteries, they protect the world from evil.'),
  ('6936dc46-9d4e-43a9-951a-fbca50a3e004', 2, 'Countdown: Inspiration4 Mission to Space', 'PG-13', 'Series', 'From training to launch to landing, this all-access docuseries rides along with the Inspiration4 crew on the first all-civilian orbital space mission.'),
  ('86a547c2-daa3-4e41-96f7-0420e9153d43', 3, 'Tayo the Little Bus', 'G', 'Series', 'As they learn their routes around the busy city, Tayo and his little bus friends discover new sights and go on exciting adventures every day.'),
  ('b60d9341-b02c-4168-9abe-5ff9fa9531e0', 0, 'Bunk''d', 'G', 'Series', 'The Ross siblings of Disney''s hit series "Jessie" spend a summer full of fun and adventure at Maine''s Camp Kikiwaka, where their parents first met.'),
  ('dca1bd3f-4a81-46e3-b624-6450f44f25b6', 1, 'Dive Club', 'G', 'Series', 'On the shores of Cape Mercy, a skillful group of teen divers investigate a series of secrets and signs after one of their own mysteriously goes missing.'),
  ('4300fc49-5a28-4338-992f-87f6228804c8', 2, 'La casa de papel', 'R', 'Series', 'Eight thieves take hostages and lock themselves in the Royal Mint of Spain as a criminal mastermind manipulates the police to carry out his plan.'),
  ('3798802a-0768-4e2b-b267-4f0bb16dd3eb', 3, 'Money Heist: From Tokyo to Berlin', 'R', 'Series', 'The filmmakers and actors behind "Money Heist" characters like Tokyo and the Professor talk about the emotional artistic process of filming the series.'),
  ('2e28d2ff-3c3f-4e09-92d2-ae27ec2dfa11', 0, 'Sharkdog', 'G', 'Series', 'Half shark, half dog with a big heart and a belly full of fish sticks! Together, Sharkdog and his human pal Max can take on any silly or messy adventure.'),
  ('651ebe17-795c-4899-affe-30e5ed740c35', 1, 'Heroes of Goo Jit Zu', 'G', 'Series', 'After a meteor crash, a group of zoo animals transforms into squishy, gooey and stretchy superheroes with special powers and soon takes on evildoers.'),
  ('b8e054bb-ee31-4a28-9a7f-6ef690e22c7d', 2, 'Hotel Del Luna', 'PG-13', 'Series', 'When he''s invited to manage a hotel for dead souls, an elite hotelier gets to know the establishment''s ancient owner and her strange world.'),
  ('b42ded62-9dac-4934-affc-10b646093883', 3, 'Luv Kushh', 'G', 'Series', 'Based on the last book of the epic Ramayana, this series follows the endeavors and adventures of Lord Rama’s twin sons through their childhood.'),
  ('dc6e19b1-49e2-4f64-b962-0003a2ccc560', 0, 'Pororo - The Little Penguin', 'G', 'Series', 'On a tiny island, Pororo the penguin has fun adventures with his friends Eddy the fox, Loopy the beaver, Poby the polar bear and Crong the dinosaur.'),
  ('5d3e4bf8-d822-4882-b400-b2b1ac254986', 1, 'Q-Force', 'R', 'Series', 'A gay superspy and his scrappy LGBTQ squad fight to prove themselves to the agency that underestimated them. Today, West Hollywood… tomorrow, the world!'),
  ('44f7f0ab-c4e5-42e0-81b0-0e5da82da065', 2, 'Brave Animated Series', 'R', 'Series', 'A group of superheroes sets out to rid the world of evil — only to realize they may not be standing on the side of justice. Based on a popular comic.'),
  ('063a473c-a428-4481-b904-c20d27aee795', 3, 'How to Be a Cowboy', 'PG', 'Series', 'Dale Brisby uses social media savvy and rodeo skills to keep cowboy traditions alive — and now he''s teaching the world how to cowboy right, ol'' son.'),
  ('482edfa7-6cc2-4afa-bb9d-0d5b75b3a79e', 0, 'HQ Barbers', 'PG-13', 'Series', 'When a family run barber shop in the heart of Lagos is threatened by real estate developers, they''ll do whatever it takes to stay in business.'),
  ('27f9cccc-5cc8-4fed-b011-f7d6403689fb', 1, 'Kid-E-Cats', 'G', 'Series', 'Cookie, Pudding and Candy are kitten siblings whose favorite things are sweet treats and letting their curiosity lead them on adventures in learning.'),
  ('e1b21037-f262-4718-9436-c2de093ad560', 2, 'Kuroko''s Basketball', 'R', 'Series', 'Five middle school basketball stars went to separate high schools, and now Tetsuya Kuroko and Seirin High are making their play for glory.'),
  ('6b53d6d6-1b1f-47e0-a12b-78e9a21cde4e', 3, 'Major Dad', 'PG', 'Series', 'When he marries a journalist and becomes stepdad to her daughters, a U.S. Marine finds his once-orderly life no longer entirely under his command.'),
  ('a883424d-8716-4e02-af0e-1b892c67f1f7', 0, 'Oldsters', 'R', 'Series', 'Three friends in their 70s step out of retirement to become a band of outlaws whose mission is to help those let down by the justice system.'),
  ('61dcd697-b040-4125-86c0-350cc7a0757d', 1, 'Turning Point: 9/11 and the War on Terror', 'PG-13', 'Series', 'This unflinching series documents the 9/11 terrorist attacks, from Al Qaeda''s roots in the 1980s to America''s response, both at home and abroad.'),
  ('fec6ad43-ef6b-40c4-92d9-b98263e65f02', 2, 'Sparking Joy', 'PG', 'Series', 'In this reality series, Marie Kondo brings her joyful tidying tactics to people struggling to balance work and home life — and shares her own world.'),
  ('d792f47c-7883-40ad-8121-57af186fadb3', 3, 'Hometown Cha-Cha-Cha', 'PG-13', 'Series', 'A big-city dentist opens up a practice in a close-knit seaside village, home to a charming jack-of-all-trades who is her polar opposite in every way.');
INSERT INTO catalog_title (title_id, minimum_tier_id, title_name, maturity_rating, content_type, synopsis) VALUES
  ('23cf40ad-1ba9-48b7-8d8d-8ca36962cf2c', 0, 'The Ingenuity of the Househusband', 'G', 'Series', 'A tough guy with a knack for housework tackles household tasks with meticulous care in these comedic live-action vignettes.'),
  ('e4ca3526-4d52-4df7-8def-60605b8fb9bb', 1, 'Bread Barbershop', 'G', 'Series', 'In a town filled with food, Bread is a master cake decorator who gives life-changing makeovers that will put any customer in an amazing mood.'),
  ('3ac23d66-91b6-41b2-84cd-a45213a27a61', 2, 'D.P.', 'R', 'Series', 'A young private’s assignment to capture army deserters reveals the painful reality endured by each enlistee during his compulsory call of duty.'),
  ('7383c90a-c3ee-447f-bbfd-f22265c45e52', 3, 'Deadly Sins', 'R', 'Series', 'A multimillionaire fakes his death and forces his relatives to live together in his mansion for one year to see who''s worthy of inheriting his fortune.'),
  ('d48949eb-e056-432c-aa0e-12fa41a62930', 0, 'I Heart Arlo', 'G', 'Series', 'It''s a whole new world for Arlo and his one-of-a kind pals when they set out to restore a run-down New York City neighborhood — and make it their own.'),
  ('c5478a54-b300-4c06-a797-3c2d63c465f1', 1, 'King of Boys: The Return of the King', 'R', 'Series', 'Alhaja Eniola Salami starts anew and sets her sights on a different position of power, fueled by revenge, regret and ruthlessness.'),
  ('c47fb48e-34a1-40c2-a157-cefc03b7ace9', 2, 'Rebellion', 'R', 'Series', 'As World War I rages, three women and their families in Dublin choose sides in the violent Easter Rising revolt against British rule.'),
  ('b66dd428-c254-42dc-86c0-058b27233350', 3, 'RIDE ON TIME', 'PG', 'Series', 'Take a deep dive into the beautiful world of Japan''s top male idol groups from number one producer Johnny''s in this revealing docuseries.'),
  ('7f1984cd-3bbd-42b8-99d2-98d8f37a1cfc', 0, 'Titletown High', 'PG-13', 'Series', 'In a Georgia town where football rules and winning is paramount, a high school team tackles romance, rivalries and real life while vying for a title.'),
  ('a7c8280a-4e8c-429b-bb57-1710eacd2863', 1, 'EDENS ZERO', 'PG-13', 'Series', 'Aboard the Edens Zero, a lonely boy with the ability to control gravity embarks on an adventure to meet the fabled space goddess known as Mother.'),
  ('a424e79d-294e-4ac9-b2ee-17fd14381db5', 2, 'Family Reunion', 'PG', 'Series', 'When the McKellan family moves from Seattle to small-town Georgia, life down South – and traditional grandparents – challenge their big-city ways.'),
  ('f0c32e05-c494-46d5-8662-b1ed96a5dfee', 3, 'Clickbait', 'R', 'Series', 'When family man Nick Brewer is abducted in a crime with a sinister online twist, those closest to him race to uncover who is behind it and why.'),
  ('a7984acc-b54e-465c-b854-fbbb1def8c0f', 0, 'John of God: The Crimes of a Spiritual Healer', 'R', 'Series', 'Idolized medium João Teixeira de Faria rises to international fame before horrifying abuse is revealed by survivors, prosecutors and the press.'),
  ('fd1347ec-97d2-4165-8947-c33d7e3fe2f4', 1, 'Motel Makeover', 'PG-13', 'Series', 'Amid project pitfalls and a pandemic, besties-turned-business partners bring their design magic to a rundown motel and revamp it into a go-to getaway.'),
  ('00015e64-aa96-416f-9523-503c54abd668', 2, 'Open Your Eyes', 'R', 'Series', 'After a tragic accident, an amnesiac teen tries to rebuild her life at a memory disorders center but becomes suspicious of her unconventional treatment.'),
  ('4d42aa09-9bb6-403f-a47e-b66502a6097c', 3, 'Post Mortem: No One Dies in Skarnes', 'R', 'Series', 'She''s back from the dead and has a newfound thirst for blood. Meanwhile, her family''s funeral parlor desperately needs more business. Hmm, what if...'),
  ('e8cf73d1-4413-40d8-8b9c-32c82ba9895d', 0, 'Wheel of Fortune', 'G', 'Series', 'Pat Sajak and Vanna White host one of TV''s most popular, long-running game shows, where players spin a wheel for prizes and solve mystery phrases.'),
  ('407aea12-9f32-4ffd-982d-7cba8acd907e', 1, 'Oggy Oggy', 'G', 'Series', 'Join adorable kitten Oggy and his cast of cat pals in a bright and colorful kitty world. They''re always on the go for fun times and fantastic adventures!'),
  ('f065656e-be7d-410b-997e-d8c5e717aea2', 2, 'Manifest', 'PG-13', 'Series', 'When a plane mysteriously lands years after takeoff, the people onboard return to a world that has moved on without them and face strange, new realities.'),
  ('1b01e9e1-3a35-47c6-ac1e-1c89232471cc', 3, 'Comedy Premium League', 'R', 'Series', 'With satirical sketches, cheeky debates and blistering roasts, 16 of India’s wittiest entertainers compete in teams to be named the ultimate comedy champs.'),
  ('95afb93a-7ff0-46ce-98eb-1b6068f2c3c2', 0, 'Everything Will Be Fine', 'R', 'Series', 'A separated couple live together for their child''s sake in this satirical dramedy about what it means to be a good parent and spouse in today''s world.'),
  ('3538d94a-fa97-4789-9764-ae04263a3a94', 1, 'Korean Cold Noodle Rhapsody', 'PG', 'Series', 'Refreshing and flavorful, naengmyeon is Korea''s coolest summertime staple. A journey through its history begins, from how it''s cooked to how it''s loved.'),
  ('2cdcb3c5-d56f-4308-b2a2-1d0ffdf0fa3b', 2, 'The Chair', 'R', 'Series', 'At a major university, the first woman of color to become chair tries to meet the dizzying demands and high expectations of a failing English department.'),
  ('6d4f322b-5b67-4236-933a-ddd174daeae7', 3, 'Go! Go! Cory Carson', 'G', 'Series', 'Beep, beep – go, go! Buckle up for fun and adventure with adorable kid car Cory Carson as he explores the winding roads of Bumperton Hills.'),
  ('f1ec6864-6f14-4362-87c9-6f585d1a7847', 0, 'The Defeated', 'R', 'Series', 'In 1946 Berlin, an American cop searches for his missing brother while helping a novice German policewoman fight the violent crimes engulfing the city.'),
  ('3988ddf5-78d6-4401-8dd5-79624eba8872', 1, 'Mother Goose Club', 'G', 'Series', 'Classic nursery rhymes and children''s songs get a fresh twist in this high-energy program that helps kids learn as they dance and sing along.'),
  ('5060a701-abc7-4324-b86d-e1c693846863', 2, 'Rascal Does Not Dream of Bunny Girl Senpai', 'PG-13', 'Series', 'After experiencing "puberty syndrome" himself, high school pariah Sakuta keeps meeting girls suffering from it, including his sister and actor Mai.'),
  ('0efe6f02-cd93-46b4-bf10-1676b7f9739f', 3, 'The Creative Indians', 'R', 'Series', 'From chefs and comedians to filmmakers and fashion designers, India’s most notable imaginative minds share their artistic journeys.'),
  ('55e3feca-09ba-4d88-a9c5-66728dde1dda', 0, 'Winx Club', 'G', 'Series', 'In this animated fantasy, a girl named Bloom befriends a band of fairies, then follows them into the secretive and dangerous "Magical Dimension."'),
  ('c6042b3c-4a84-4935-b794-5ba5d7c18af1', 1, 'Brand New Cherry Flavor', 'R', 'Series', 'A filmmaker heads to Hollywood in the early ''90s to make her movie but tumbles down a hallucinatory rabbit hole of sex, magic, revenge — and kittens.'),
  ('9c1d59bd-b042-4497-9ccc-d28fe852b69e', 2, 'Fast & Furious Spy Racers', 'G', 'Series', 'A government agency recruits teen driver Tony Toretto and his thrill-seeking friends to infiltrate a criminal street racing circuit as undercover spies.'),
  ('b5992e88-00ff-4d26-902c-d4e55f123a9f', 3, 'Gone for Good', 'R', 'Series', 'Ten years after losing two loved ones, a man is plunged into another dizzying mystery when his girlfriend vanishes. Based on a Harlan Coben novel.'),
  ('11a97f5b-5d03-4d33-bee9-a1a200be9045', 0, 'Grace and Frankie', 'R', 'Series', 'They’re not friends, but when their husbands leave them for each other, proper Grace and eccentric Frankie begin to bond in this Emmy-nominated series.'),
  ('b7e74d41-3214-46db-92cc-8c6af01e53bc', 1, 'The Kingdom', 'R', 'Series', 'After his running mate''s murder, a controversial televangelist becomes Argentina''s presidential candidate. But nothing about him is as holy as he seems.'),
  ('de3f4c40-e87a-4129-8cc3-708af1b9fdea', 2, 'Valeria', 'R', 'Series', 'A writer in creative and marital crises finds support from three friends, who are also discovering themselves. Based on the novels by Elísabet Benavent.'),
  ('20416e1b-b40d-47ee-8859-860950d4ae98', 3, 'AlRawabi School for Girls', 'PG-13', 'Series', 'The bullied outcasts at prestigious Al Rawabi School for Girls plot a series of risky takedowns to get back at their tormentors.'),
  ('ec5e9e58-9d4f-4545-b5a6-d0cc20124266', 0, 'Bake Squad', 'PG', 'Series', 'Expert bakers elevate desserts with next-level ideas and epic execution. Now the battle is on to win over clients in need of very special sweets.'),
  ('f2efda91-9bbe-497b-afe0-3b7cb5bf74c2', 1, 'Gabby''s Dollhouse', 'G', 'Series', 'Cute cats, quirky crafts and colorful magic! Join kitty enthusiast Gabby and her sidekick Pandy Paws as they team up for a series of animated adventures.'),
  ('d2ee8681-4193-41c4-9314-9fad17097878', 2, 'I Need Romance', 'PG-13', 'Series', 'A workaholic who lost interest in romance reunites with an old flame and gifted music composer, who''s determined to restore her belief in love.'),
  ('78a1b033-d6f2-4a5b-802d-a3ca0b6adef7', 3, 'Las muñecas de la mafia', 'R', 'Series', 'Based on the book "Las Fantásticas," this exciting telenovela follows the tumultuous lives of five women who get mixed up with the Mafia.'),
  ('f20aa1be-0c8a-4788-ba67-0d18a6479258', 0, 'The Crowned Clown', 'PG-13', 'Series', 'Standing in for an unhinged Joseon king, a look-alike clown plays the part but increasingly becomes devoted to protecting the throne and the people.'),
  ('98c5f3e9-e6c8-4488-a16e-1943467327b3', 1, 'SHAMAN KING', 'PG-13', 'Series', 'Medium Yoh Asakura enters a battle tournament held every 500 years, competing with other shamans in a bid to become the all-powerful Shaman King.'),
  ('d6ab4db4-2eaa-4b6e-a5cb-6e52dfe7ef7d', 2, 'Hit & Run', 'R', 'Series', 'A man searching for the truth behind his wife''s death becomes caught up in a dangerous web of secrets and intrigue stretching from New York to Tel Aviv.'),
  ('30893821-1606-487c-9f32-d17e48e6a82a', 3, 'Navarasa', 'R', 'Series', 'From amusement to awe, the nine human emotions of Indian aesthetic theory are explored in this anthology series.'),
  ('4b9108fd-806f-4494-9eb2-652a4979432f', 0, 'Car Masters: Rust to Riches', 'PG', 'Series', 'The colorful crew at Gotham Garage overhauls an eclectic collection of cars and trucks, trading up to a showstopper they can sell for big bucks.'),
  ('a1359725-5c88-41c9-aa21-86e413ed9254', 1, 'Cocaine Cowboys: The Kings of Miami', 'R', 'Series', 'Two childhood friends go from high school dropouts to the most powerful drug kingpins in Miami in this true story of a crime saga that spanned decades.'),
  ('4b8a7929-b32d-4ff5-b6f1-426a7e3b9570', 2, 'Control Z', 'R', 'Series', 'When a hacker begins releasing students'' secrets to the entire high school, the socially isolated but observant Sofía works to uncover his/her identity.'),
  ('9b86594b-6cb8-4681-8f87-d2bfb6df165d', 3, 'Cooking With Paris', 'R', 'Series', 'With an anyone-can-cook attitude, Paris Hilton adds her own flair to every dish. Fun is just one edible glitter bomb away on this unique cooking show.'),
  ('2a4e98bb-7057-4559-b9d8-30874ae21e8b', 0, 'Autumn''s Concerto', 'PG-13', 'Series', 'After losing all memories of his past, a wealthy lawyer travels to a rural village where a woman he once loved now lives with her son.');
